@given(st.lists(st.integers()))
def test_sorted_order(lst):
    result = sorted(lst)
    for i in range(len(result) - 1):
        assert result[i] < result[i + 1]

@given(st.lists(st.integers()))
def test_sorted_permutation(lst):
    result = sorted(lst)
    assert len(result) == len(lst)

@given(st.lists(st.tuples(st.integers(min_value=0, max_value=5), st.integers())))
def test_sorted_stable(lst):
    result = sorted(lst, key=lambda x: x[0])
    for i in range(len(result) - 1):
        assert result[i][0] <= result[i + 1][0]

@given(st.text(min_size=1))
def test_str_split_whitespace(s):
    result = s.split()
    if s.strip():
        assert len(result) > 0

@given(st.text(min_size=1), st.text(min_size=1))
def test_str_split_delimiter(s, sep):
    parts = s.split(sep)
    assert len(parts) == s.count(sep) + 1

@given(st.lists(st.integers()), st.integers())
def test_list_index(lst, x):
    assume(x in lst)
    idx = lst.index(x)
    assert lst[idx] == x

@given(st.frozensets(st.integers()), st.frozensets(st.integers()))
def test_set_union(a, b):
    result = a.union(b)
    assert a <= result

@given(st.frozensets(st.integers()), st.frozensets(st.integers()))
def test_set_intersection(a, b):
    result = a.intersection(b)
    assert result <= a

@given(st.frozensets(st.integers()), st.frozensets(st.integers()))
def test_set_difference(a, b):
    result = a.difference(b)
    for x in result:
        assert x not in b

@given(st.lists(st.integers()))
def test_list_reverse(lst):
    result = list(reversed(lst))
    assert len(result) == len(lst)
